// ───────── PARAMS : 런타임에 만지는 값 ─────────
// 프로토타입의 Tweaks 패널과 1:1 대응한다. 값을 바꾼 뒤 apply() 를 부르면 즉시 반영된다.
//
//   PB.params.lineOpacity = 0.4;  PB.apply();     // 콘솔에서
//
// 셰이더 유니폼으로 매 프레임 밀리는 값(swell, ripple, driftSpeed 등)은 apply() 없이도 따라온다.
// apply() 가 필요한 값은 재질/색/가시성처럼 프레임 루프가 다시 쓰지 않는 것들이다.

